mapper.select:
select * from `cart`

     and user_id = #{userId}
     and goods_id = #{goodsId}

order by id desc

mapper.update:
update `cart` set goods_id = #{goodsId}, user_id = #{userId}, num = #{num},
    goods_name = #{goodsName}, goods_img = #{goodsImg}, price = #{price}, create_time = #{createTime}
where id = #{id}
